/* VHN Labs: instala os jogos como aplicativo e guarda o site para abrir sem internet. */
const V='vhn-v3',BASE=['./','./index.html'];
const ICONES={"colheita192":"","colheita512":"","bolinhas192":"","bolinhas512":""};
const APPS={"colheita": ["A Colheita do Silêncio 2D", "Colheita", "#030806"], "bolinhas": ["Bolinhas Coloridas", "Bolinhas", "#0a1a44"]};
function manifesto(id){
  const a=APPS[id],sc=self.registration.scope,ic=t=>sc+'icone-'+id+'-'+t+'.png';
  return JSON.stringify({id:sc+'?jogo='+id,name:a[0],short_name:a[1],description:a[0]+' - VHN Labs',lang:'pt-BR',start_url:sc+'?jogo='+id,scope:sc,display:'standalone',background_color:a[2],theme_color:a[2],
    icons:[{src:ic(192),sizes:'192x192',type:'image/png',purpose:'any'},{src:ic(512),sizes:'512x512',type:'image/png',purpose:'any'},{src:ic(512),sizes:'512x512',type:'image/png',purpose:'maskable'}]});
}
function png(k){const b=atob(ICONES[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return new Response(u,{headers:{'Content-Type':'image/png','Cache-Control':'max-age=86400'}})}
self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>Promise.all(BASE.map(u=>c.add(u).catch(()=>0)))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==V).map(x=>caches.delete(x)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{
  const r=e.request;if(r.method!=='GET')return;
  const u=new URL(r.url);
  const m=u.origin===location.origin&&u.pathname.match(/manifest-(colheita|bolinhas)\.webmanifest$/);
  if(m){e.respondWith(new Response(manifesto(m[1]),{headers:{'Content-Type':'application/manifest+json'}}));return}
  const p=u.origin===location.origin&&u.pathname.match(/icone-(colheita|bolinhas)-(192|512)\.png$/);
  if(p){e.respondWith(png(p[1]+p[2]));return}
  if(u.origin===location.origin&&u.searchParams.has('v'))return; /* verificação de atualização: sempre da internet */
  if(u.origin===location.origin&&r.mode==='navigate'){
    e.respondWith(fetch(r).then(x=>{if(x.ok&&!u.search){const c=x.clone();caches.open(V).then(h=>h.put('./index.html',c))}return x}).catch(()=>caches.match('./index.html')));return}
  if(u.origin===location.origin||/fonts\.(googleapis|gstatic)\.com$/.test(u.hostname)){
    e.respondWith(caches.match(r).then(h=>h||fetch(r).then(x=>{if(x&&(x.ok||x.type==='opaque')){const c=x.clone();caches.open(V).then(k=>k.put(r,c))}return x}).catch(()=>h)))}
});
